using System;
using System.Linq;
using MET.Core;
using UnityEngine;
namespace MET.City {
public sealed partial class CityInterface {
 RectTransform BonusCard(Transform parent,string bid){var data=Bonus.card(G,bid);var card=Card(parent,data["name"].Text,data["grade"].Text+" · "+V.Map("building","建筑方案","organization","运营商方案","block","本街区方案").Get(data["scope"],data["scope"]).Text,Gold);Metric(card,"库存副本",data["copies"].Long+" 份");Label(card,data["preview_reason"].Text,16,Muted);EffectRows(card,data["effects"]);Fold(card,"完整规则与重复说明",c=>{Label(c,data["stacking_note"].Text,15,Muted,70);Raw(c,Rules.bonus_rules(G,bid,1,data["blueprint_level"].Long>2?2:(int)data["blueprint_level"].Long));});return card;}
 void EffectRows(Transform parent,V rows){foreach(var effect in rows)Metric(parent,effect.Get("label","效果").Text,F(effect.Get("before",0).Double,3)+" → "+F(effect.Get("after",0).Double,3)+effect.Get("unit","").Text);}
 void BonusesPage(){BlueprintInventoryPage();}
 void RewardCard(V reward,bool actionable){BlueprintRewardCard(reward,actionable);}
 void ThemesPage(){var view=Themes.view(G);ThemeEvents(_body,view);var rewards=Bonus.pending(G);if(rewards.Count>0){var queue=Card(_body,"已保存的奖励队列","共有 "+rewards.Count+" 份待选奖励。年度与主题奖励按保存顺序领取，前序候选不会被主题页隐藏。",Gold);Button(queue,"先处理奖励队列 ›",()=>Navigate("settlement"),true);}if(view["id"].Text==""){Label(_body,"选择街区的发展主题",28,Gold);Label(_body,"委任定义本区本轮成长方向；选择不消耗 DT，改向必须持有真实重铸权并支付代价。",17,Muted);var row=Row(_body,"Theme Choices",320);foreach(var choice in view["choices"]){var id=choice["id"].Text;var box=Card(row,choice["name"].Text,choice["description"].Text,Green);Illustration(box,ThemePicture(id),120);Button(box,"选择此主题",()=>Command(g=>Themes.select(g,id)),true);}}
  else {var progress=Card(_body,view["name"].Text,view["completed"].Bool?"主题已经完成":"第 "+view["stage"].Long+" 阶段 · "+view["stage_name"].Text,view["completed"].Bool?Gold:Green);var steps=Row(progress,"Stage Track",68);foreach(var n in new[]{1,2,3})Label(steps,(view["stage"].Long>=n?"● ":"○ ")+"M"+n,24,view["stage"].Long>=n?Green:Muted);foreach(var goal in view["goals"]){var target=goal["target"].Double;var displayFactor=goal["unit"].Text=="%"?100.0:1.0;Meter(progress,goal["label"].Text,goal["value"].Double*displayFactor,target*displayFactor," "+goal["unit"].Text,goal["met"].Bool?Green:Gold);if(goal["comparison"].Text=="max")Label(progress,"目标为不高于 "+F(target*displayFactor)+goal["unit"].Text+"，不是越高越好。",14,Muted);if(goal["kind"].Text=="delivery"&&!goal["met"].Bool&&goal["id"].Text.StartsWith("delivery_",StringComparison.Ordinal)){var resource=goal["id"].Text.Substring("delivery_".Length);Button(progress,"从库存交付 "+Resource(resource),()=>Command(g=>Themes.deliver(g,resource)),true);}}
   if(view["steady_required_seconds"].Double>0)Meter(progress,"状态稳定时长",view["steady_seconds"].Double/G.c.beta["units"]["earth_seconds_per_month"].Double,view["steady_required_seconds"].Double/G.c.beta["units"]["earth_seconds_per_month"].Double," 来生月",Green);Metric(progress,"重铸权",view["reforge_tokens"].Long+" 份");if(view["can_reforge"].Bool){Fold(progress,"消耗重铸权与 DT 改向",c=>{Label(c,"每次支付1份重铸权 + "+F(view["reforge_dt_cost"].Double,2)+" DT；已有与待领成果保留。",16,Gold);foreach(var candidate in view["choices"]){var id=candidate["id"].Text;if(id==view["id"].Text)continue;Button(c,"改向「"+candidate["name"].Text+"」",()=>Confirm("确认重铸主题？","消耗1份重铸权与 "+F(view["reforge_dt_cost"].Double,2)+" DT，已有和待领奖励保留。",()=>Command(g=>Themes.reforge(g,id))));}});}
   Fold(progress,"主题定义与完整阶段要求",c=>Raw(c,Themes._definition(G,view["id"].Text)));
  }
  var history=Card(_body,"主题进展记录","只展示实际发生的选向、阶段、合同与完成记录。",Blue);foreach(var entry in view["history"].Reverse()){Label(history,entry.Get("name",entry.Get("id","主题")).Text+" · "+entry.Get("status_label","城市记录").Text,18);if(entry.Get("reason","").Text!="")Label(history,entry["reason"].Text,15,Muted,60);Fold(history,"来源凭据",c=>Raw(c,entry));}
 }
 void ThemeEvents(Transform parent,V view){PlanningTaskEvents(parent,view);}
 void LegacyThemeEvents(Transform parent,V view){foreach(var eventValue in view["events"]){var evt=eventValue;var id=evt["id"].Text;var def=evt.Get("definition",Themes._event_definition(G,id));var offered=evt["status"].Text=="offered";var box=Card(parent,evt["name"].Text,evt["description"].Text,offered?Gold:Blue);Label(box,offered?"等待决定":"合同进行中",18,Gold);var deadline=evt["deadline_seconds"].Double;if(deadline>=0)Metric(box,"真实期限",Clock.duration(G,deadline));else if(offered&&def.Get("choices",V.Arr()).Count==0&&def.Get("deadline_months",0).Double>0)Metric(box,"接受后期限",F(def["deadline_months"].Double)+" 来生月");if(!offered&&evt.Get("target",0).Double>0)Meter(box,"实际进度",evt["progress"].Double*(evt.Get("unit","").Text=="%"?100:1),evt["target"].Double*(evt.Get("unit","").Text=="%"?100:1)," "+evt.Get("unit","单位").Text,Blue);
   if(!offered){
   var cost=def.Get("currency",0).Double+def.Get("deposit",0).Double;
   if(cost>0)Metric(box,offered?"接受时支付":"接受时已支付",F(cost)+"通货");else Label(box,"无即时通货支付。",15,Muted);
   foreach(var resource in def.Get("resources",V.Map()).Keys)Metric(box,(offered?"接受时扣除 ":"接受时已扣 ")+Resource(resource),F(def["resources"][resource].Double));
   if(def.Get("deposit",0).Double>0)Label(box,"成功退还保证金 "+F(def["deposit"].Double)+"通货；逾期只失去机会与已付保证金。",15,Gold,55);
   if(def.Get("cash_reward",0).Double>0)Metric(box,"成功通货奖励",F(def["cash_reward"].Double));
   if(def.Get("reward_kind","").Text!="")Label(box,def["reward_kind"].Text=="research"?"成功后获得蓝图研究机会，按奖励队列领取。":"成功后获得方案副本选择，按奖励队列领取。",16,Green);
   if(def.Get("arrival_people",0).Double>0)Metric(box,"成功后真实迁入",F(def["arrival_people"].Double)+"人（带来真实需求）");
   if(def.Get("delivery_resource","").Text!="")Metric(box,"交付目标",Resource(def["delivery_resource"].Text)+" "+F(def.Get("delivery_amount",0).Double));   }
   var alternatives=offered&&evt["choices"].Count>2?Row(box,"Theme event alternatives",280*TextScale):(RectTransform)box;foreach(var choiceValue in evt["choices"]){var choice=choiceValue;var choiceId=choice["id"].Text;var option=offered?Card(alternatives,choice["label"].Text,choice.Get("description","").Text,choiceId=="decline"?Blue:Gold):box;var costText=choice.Get("cost_text","").Text;if(offered&&costText!="")Label(option,costText,17,Gold,105);Button(option,offered?"选择 · "+choice["label"].Text:choice["label"].Text,()=>Command(g=>Themes.choose_event(g,id,choiceId)),choiceId!="decline",!choice.Get("available",true).Bool);}if(offered)Label(box,"婉拒不支付代价，也不增加惩罚。",15,Muted);if(!offered&&evt["delivery_remaining"].Double>0){var resource=evt["delivery_resource"].Text;Button(box,"交付 "+Resource(resource)+" · 还需 "+F(evt["delivery_remaining"].Double),()=>Command(g=>Themes.deliver(g,resource,-1,id)),true);}Fold(box,"出现条件、成功结果与合同细则",c=>Raw(c,def));}}
 void SettlementPage(){var ending=S["block"].Get("ending",V.Map());var triggered=ending.Get("triggered",false).Bool;if(triggered){var intro=Card(_body,"高速发展预算已耗尽","街区可继续常速经营；命名权、地标资格和构筑证据固定在 DT 首次实际归零时。",Gold);Metric(intro,"街区人口",F(S["metrics"].Get("population",0).Double)+" 人");Metric(intro,"已使用 DT",F(S["totals"]["dt_used"].Double,2));if(S["block"].Get("naming_rights",false).Bool){var name=InputBox(intro,"","为这个街区命名");name.characterLimit=(int)G.c.v040["progression"].Get("name_max_length",24).Long;Button(intro,"保存街区名称",()=>Command(g=>Block.name_block(g,name.text)),true);}else Label(intro,"街区名称已保存："+S["block"]["display_name"].Text,24,Gold);
   var eligible=ending.Get("eligible_theme","").Text;var landmark=Block.capstone_definitions(G).Get(eligible,V.Map());if(landmark.Count!=0){var cap=Card(_body,landmark.Get("name","主题定型建筑").Text,"主题已完成 · 具备正式挂牌资格",CityWorld.BuildingTypeColor("special"));Mark(cap,"public",CityWorld.BuildingTypeColor("special"),130);Button(cap,ending.Get("capstone_claimed",false).Bool?"已经正式挂牌":"正式挂牌 · 领取定型建筑",()=>Command(g=>Block.claim_capstone(g)),true,ending.Get("capstone_claimed",false).Bool);Fold(cap,"完整规则与来源",c=>Raw(c,landmark));}else Label(intro,"本次未达成主题奖励条件。继续经营可完成主题，但不追补此次地标资格。",17,Muted,60);
   BuildLegacyCards(_body,true);
   Button(intro,"扩展同城 · 新街区",()=>Navigate("block_start"));Button(intro,"查看下一地区任期",()=>Navigate("district_start"));
   Button(intro,"保存街区记录",()=>Command(g=>{var result=Block.archive(g);return result.Get("ok",false).Bool?"":result.Get("error","记录保存失败。").Text;}));Button(intro,"查看地区治理与后续发展",()=>Navigate("governance"),true);
  }else {var intro=Card(_body,"街区发展结算","年度与两年大周期按稳定顺序合并，奖励候选持久保存。",Gold);Metric(intro,"当前来生日期",Clock.summary(G)["date"].Text);var next=Cycles.next_boundary_seconds(G);Metric(intro,"下一年度 / 安居边界",Clock.duration(G,next));}
  foreach(var summary in S["block"].Get("cycles",V.Map()).Get("pending_summaries",V.Arr())){var box=Card(_body,"第 "+summary["year"].Long+" 年"+(summary["major_cycle"].Bool?" / 两年大周期":""),"来自实际周期结算，不同单位分别呈现。",Blue);Metric(box,"人口变化",Signed(summary["population_delta"].Double)+" 人");Metric(box,"财政变化",Signed(summary["currency_delta"].Double)+" 通货");Fold(box,"周期前后完整快照",c=>Raw(c,summary));}
  var pending=Bonus.pending(G);for(var i=0;i<pending.Count;i++)RewardCard(pending[i],i==0);ThemeEvents(_body,Themes.view(G));var nextActions=Card(_body,triggered?"接下来 / 留在这个街区":"完成本次结算","待选奖励与事件处理完毕后，返回常速经营。",Green);Button(nextActions,triggered?"稍后命名 · 继续常速经营":"完成结算 · 返回常速经营",()=>{Runtime.ResumeNormal();if(!Runtime.PendingDecisions)CloseArchive();},true,Runtime.PendingDecisions);
 }
}
